files.bin/retain.sh:
#!/bin/sh
set -eu
. ./lib/catalog.sh
. ./lib/guard.sh
retain_main() {
    catalog_load "$1"
    guard_window "$RETENTION_DAYS" || return $?
    printf '%s\n' "$SNAPSHOT_GROUP"
}
retain_main "$@"

files.lib/guard.sh:
guard_window() {
    if [ "$1" -lt 3 ]; then
        printf '%s\n' 'RETENTION_TOO_SHORT' >&2
        return 47
    fi
}
